   737→// =============================================================================
   738→// Delete Task
   739→// =============================================================================
   740→
   741→/**
   742→ * Delete a task
   743→ */
   744→export function deleteTask(repoRoot: string, taskName: string): DeleteTaskResult {
   745→  const taskDir = resolveTaskDirectory(taskName, repoRoot);
   746→
   747→  if (!taskDir || !existsSync(taskDir)) {
   748→    return {
   749→      success: false,
   750→      error: `Task not found: ${taskName}`,
   751→    };
   752→  }
   753→
   754→  // Use rm -rf to delete the directory
   755→  execSync(`rm -rf "${taskDir}"`, { cwd: repoRoot });
   756→
   757→  return {
   758→    success: true,
   759→    deleted: taskName,
   760→  };
   761→}
   762→
   763→// =============================================================================
   764→// Finish Task
   765→// =============================================================================
   766→
   767→/**
   768→ * Finish a task - mark as completed
   769→ */
   770→export function finishTask(repoRoot: string, taskName: string): FinishTaskResult {
   771→  const tasksDir = getTasksDir(repoRoot);
   772→
   773→  // Find task directory
   774→  const taskDir = findTaskByName(taskName, tasksDir);
   775→  if (!taskDir || !existsSync(taskDir)) {
   776→    return {
   777→      success: false,
   778→      error: `Task not found: ${taskName}`,
   779→    };
   780→  }
   781→
   782→  return {
   783→    success: true,
   784→    cleared: taskDir,
   785→  };
   786→}
