   788→// =============================================================================
   789→// Archive Task
   790→// =============================================================================
   791→
   792→/**
   793→ * Archive a completed task
   794→ */
   795→export function archiveTask(repoRoot: string, taskName: string): ArchiveTaskResult {
   796→  const tasksDir = getTasksDir(repoRoot);
   797→
   798→  // Find task directory
   799→  const taskDir = findTaskByName(taskName, tasksDir);
   800→  if (!taskDir || !existsSync(taskDir)) {
   801→    return {
   802→      success: false,
   803→      error: `Task not found: ${taskName}`,
   804→    };
   805→  }
   806→
   807→  const dirName = taskDir.split("/").pop() || "";
   808→  const taskJsonPath = join(taskDir, FILE_TASK_JSON);
   809→
   810→  // Update status before archiving
   811→  const today = getTodayDate();
   812→  if (existsSync(taskJsonPath)) {
   813→    const taskData = readTaskJson(taskDir);
   814→    if (taskData) {
   815→      taskData.status = "completed";
   816→      taskData.completed_at = today;
   817→      writeTaskJson(taskDir, taskData);
   818→    }
   819→  }
   820→
   821→  // Archive the task
   822→  const archiveDest = archiveTaskToDir(taskDir, repoRoot);
   823→  if (archiveDest) {
   824→    const yearMonth = getYearMonth();
   825→    return {
   826→      success: true,
   827→      archived: dirName,
   828→      destination: `archive/${yearMonth}/`,
   829→    };
   830→  } else {
   831→    return {
   832→      success: false,
   833→      error: "Failed to move task to archive",
   834→    };
   835→  }
   836→}
   837→
   838→// =============================================================================
   839→// List Archived Tasks
   840→// =============================================================================
   841→
   842→/**
   843→ * List archived tasks
   844→ */
   845→export function listArchivedTasks(
   846→  repoRoot: string,
   847→  month?: string
   848→): ListArchiveResult {
   849→  const archived = getArchivedTasks(repoRoot, month);
   850→
   851→  return {
   852→    success: true,
   853→    archived,
