    55→/**
    56→ * Convert UnifiedTask to db Task for events
    57→ * Now uses unified status directly since DbTaskStatus is the same
    58→ */
    59→function toDbTask(task: UnifiedTask): Task {
    60→  return {
    61→    id: task.id,
    62→    title: task.title || task.prompt?.slice(0, 50) || "Untitled",
    63→    description: task.description || task.prompt,
    64→    status: task.status as DbTaskStatus,
    65→    agentId: task.agent,
    66→    created_at: task.created_at,
    67→    updated_at: task.updated_at || task.created_at,
    68→  };
    69→}
    70→
    71→/**
    72→ * Parse subtasks into structured format
    73→ * If subtaskDetails exists, use it; otherwise parse from subtasks string array
    74→ */
    75→function parseSubtasksDetail(task: UnifiedTask): SubtaskInfo[] | null {
    76→  // Prefer structured subtaskDetails if available
    77→  if (task.subtask_details && task.subtask_details.length > 0) {
    78→    return task.subtask_details;
    79→  }
    80→
    81→  // Parse from legacy subtasks string array if available
    82→  if (task.subtasks && task.subtasks.length > 0) {
    83→    return task.subtasks.map((name, index) => ({
    84→      id: `subtask_${index}`,
    85→      name,
    86→      status: "pending" as const,
    87→    }));
    88→  }
    89→
    90→  return null;
    91→}
