  1273→    const { workspace_path, task_dirs, event_type, payload } = request.body;
  1274→
  1275→    // Validate workspace_path
  1276→    if (!workspace_path) {
  1277→      reply.code(400);
  1278→      return { error: "workspace_path is required" };
