  1284→      return { error: `Invalid event type: ${event_type}` };
  1285→    }
  1286→
  1287→    // Validate task_dirs
  1288→    if (!task_dirs || task_dirs.length === 0) {
  1289→      reply.code(400);
  1290→      return { error: "task_dirs must be a non-empty array" };
  1291→    }
  1292→
  1293→    // Process each task
  1294→    const results = await Promise.all(
  1295→      task_dirs.map(async (taskDirOrId) => {
