    90→interface WorkspaceSettingsDialogProps {
    91→  open: boolean;
    92→  onOpenChange: (open: boolean) => void;
    93→  workspaceId: string | null;
    94→}
    95→
    96→export function WorkspaceSettingsDialog({
    97→  open,
    98→  onOpenChange,
    99→  workspaceId,
   100→}: WorkspaceSettingsDialogProps) {
   101→  const { t } = useTranslation();
   102→  const prefersReducedMotion = useReducedMotion();
   103→  const { getWorkspace } = useLocalWorkspaces();
   104→
   105→  const [activeSection, setActiveSection] = useState<WorkspaceSettingsSection>("general");
   106→
   107→  // Get workspace data
   108→  const workspace = workspaceId ? getWorkspace(workspaceId) : null;
   109→
   110→  // Reset to general section when dialog opens
   111→  useEffect(() => {
   112→    if (open) {
   113→      setActiveSection("general");
   114→    }
   115→  }, [open]);
   116→
   117→  // Animation variants
   118→  const tabContentVariants = {
   119→    initial: {
   120→      opacity: 0,
   121→      x: prefersReducedMotion ? 0 : 20,
   122→    },
   123→    animate: {
   124→      opacity: 1,
   125→      x: 0,
   126→      transition: {
   127→        duration: prefersReducedMotion ? 0 : 0.3,
   128→        ease: easeOutExpo,
   129→      },
   130→    },
   131→    exit: {
   132→      opacity: 0,
   133→      x: prefersReducedMotion ? 0 : -20,
   134→      transition: {
   135→        duration: prefersReducedMotion ? 0 : 0.2,
   136→      },
   137→    },
   138→  };
   139→
   140→  const containerVariants = {
   141→    hidden: { opacity: 0 },
   142→    visible: {
   143→      opacity: 1,
   144→      transition: {
   145→        staggerChildren: prefersReducedMotion ? 0 : 0.05,
   146→        delayChildren: prefersReducedMotion ? 0 : 0.05,
   147→      },
   148→    },
   149→  };
   150→
   151→  const itemVariants = {
   152→    hidden: { opacity: 0, y: prefersReducedMotion ? 0 : 12 },
   153→    visible: {
   154→      opacity: 1,
   155→      y: 0,
   156→      transition: {
   157→        duration: prefersReducedMotion ? 0 : 0.3,
   158→        ease: easeOutExpo,
   159→      },
   160→    },
   161→  };
   162→
   163→  // Render section content
   164→  const renderSectionContent = () => {
   165→    if (!workspace) return null;
   166→
   167→    switch (activeSection) {
   168→      case "general":
   169→        return <GeneralSection key="general" workspace={workspace} />;
   170→      case "executors":
   171→        return <ExecutorsSection key="executors" workspace={workspace} />;
   172→      case "agents":
   173→        return <AgentsSection key="agents" workspace={workspace} />;
   174→      case "mcp":
   175→        return <McpSection key="mcp" workspace={workspace} />;
   176→      case "skills":
   177→        return <SkillsSection key="skills" workspace={workspace} />;
   178→      case "github":
   179→        return <GitHubSettingsSection key="github" workspace={workspace} />;
   180→      case "about":
   181→        return <AboutSection key="about" workspace={workspace} />;
   182→      default:
   183→        return null;
   184→    }
   185→  };
   186→
   187→  if (!workspace) return null;
   188→
   189→  return (
   190→    <Dialog open={open} onOpenChange={onOpenChange}>
   191→      <DialogContent className="max-w-5xl w-[90vw] h-[85vh] p-0 gap-0 overflow-hidden">
   192→        <motion.div
   193→          className="h-full flex flex-col md:flex-row"
   194→          variants={containerVariants}
   195→          initial="hidden"
   196→          animate="visible"
   197→        >
   198→          {/* Left Navigation Sidebar */}
   199→          <motion.nav
   200→            className="w-full md:w-56 shrink-0 border-b md:border-b-0 md:border-r bg-muted/30 p-4"
   201→            variants={itemVariants}
   202→          >
   203→            <div className="flex items-center gap-2 mb-4 px-2">
   204→              <FolderOpen className="h-5 w-5 text-primary" />
   205→              <h1 className="text-lg font-semibold font-serif truncate">
   206→                {workspace.name}
   207→              </h1>
   208→            </div>
   209→            <ul className="space-y-1">
   210→              {SECTIONS.map((section) => {
   211→                const Icon = section.icon;
   212→                const isActive = activeSection === section.id;
   213→
   214→                return (
   215→                  <li key={section.id}>
   216→                    <button
   217→                      onClick={() => setActiveSection(section.id)}
   218→                      className={cn(
   219→                        "w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm",
   220→                        "transition-all duration-200",
   221→                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
   222→                        isActive
   223→                          ? [
   224→                              "bg-primary text-primary-foreground font-medium",
   225→                              "shadow-sm",
   226→                            ]
   227→                          : [
   228→                              "text-muted-foreground",
   229→                              "hover:bg-muted hover:text-foreground",
   230→                            ]
   231→                      )}
   232→                    >
   233→                      <Icon
   234→                        className={cn(
   235→                          "h-4 w-4 shrink-0",
   236→                          "transition-transform duration-200",
   237→                          isActive && "scale-110"
   238→                        )}
   239→                      />
   240→                      <span>{t(section.labelKey)}</span>
   241→                    </button>
   242→                  </li>
   243→                );
   244→              })}
   245→            </ul>
   246→          </motion.nav>
   247→
   248→          {/* Right Content Area */}
   249→          <div className="flex-1 overflow-auto p-6">
   250→            <AnimatePresence mode="wait">
   251→              <motion.div
   252→                key={activeSection}
   253→                variants={tabContentVariants}
   254→                initial="initial"
   255→                animate="animate"
   256→                exit="exit"
   257→                className="max-w-2xl"
   258→              >
   259→                {renderSectionContent()}
   260→              </motion.div>
   261→            </AnimatePresence>
   262→          </div>
   263→        </motion.div>
   264→      </DialogContent>
   265→    </Dialog>
   266→  );
   267→}
