   767→/**
   768→ * Write ideas to a markdown file
   769→ *
   770→ * Each idea is written as a section with YAML frontmatter.
   771→ *
   772→ * @param filePath - Path to write the file
   773→ * @param ideas - Array of ideas to write
   774→ */
   775→export function writeIdeasToFile(filePath: string, ideas: Idea[]): void {
   776→  const sections: string[] = [];
   777→
   778→  for (const idea of ideas) {
   779→    const frontmatter: string[] = [
   780→      "---",
   781→      `id: ${idea.id}`,
   782→      `type: ${idea.type}`,
   783→      `title: ${idea.title}`,
   784→      `description: ${idea.description}`,
   785→      `rationale: ${idea.rationale}`,
   786→      `estimated_effort: ${idea.estimatedEffort}`,
   787→      `status: ${idea.status}`,
   788→      `promoted_to: ${idea.promotedTo || "null"}`,
   789→      `created_at: ${idea.created_at}`,
   790→    ];
   791→
   792→    // Add affected files to frontmatter as YAML array
   793→    if (idea.affectedFiles && idea.affectedFiles.length > 0) {
   794→      frontmatter.push("affected_files:");
   795→      for (const file of idea.affectedFiles) {
   796→        frontmatter.push(`  - ${file}`);
   797→      }
   798→    }
   799→
   800→    // Add existing patterns to frontmatter as YAML array
   801→    if (idea.existingPatterns && idea.existingPatterns.length > 0) {
   802→      frontmatter.push("existing_patterns:");
   803→      for (const pattern of idea.existingPatterns) {
   804→        frontmatter.push(`  - ${pattern}`);
   805→      }
   806→    }
   807→
   808→    frontmatter.push("---");
   809→
   810→    // Body contains implementation approach directly
   811→    const body = idea.implementationApproach || "";
   812→
   813→    sections.push(frontmatter.join("\n") + "\n\n" + body);
   814→  }
   815→
   816→  const content = sections.join("\n---\n\n");
   817→  writeFileSync(filePath, content, "utf-8");
   818→}
   819→
   820→/**
   821→ * Write a single idea to its own file
   822→ *
   823→ * @param sessionDir - Session directory path
   824→ * @param idea - Idea to write
   825→ * @returns The filename that was written
   826→ */
   827→export function writeSingleIdeaToFile(sessionDir: string, idea: Idea): string {
   828→  // Use name if available, fallback to id
   829→  const ideaName = idea.name || idea.id;
   830→  const filePath = getSingleIdeaFilePath(sessionDir, idea.type, ideaName);
   831→  const fileName = getSingleIdeaFileName(idea.type, ideaName);
   832→
   833→  const frontmatter: string[] = [
   834→    "---",
   835→    `id: ${idea.id}`,
   836→    `type: ${idea.type}`,
   837→    `name: ${ideaName}`,
   838→    `title: ${idea.title}`,
   839→    `description: ${idea.description}`,
   840→    `rationale: ${idea.rationale}`,
   841→    `estimated_effort: ${idea.estimatedEffort}`,
   842→    `status: ${idea.status}`,
   843→    `promoted_to: ${idea.promotedTo || "null"}`,
   844→    `created_at: ${idea.created_at}`,
   845→  ];
   846→
   847→  // Add affected files to frontmatter as YAML array
   848→  if (idea.affectedFiles && idea.affectedFiles.length > 0) {
   849→    frontmatter.push("affected_files:");
   850→    for (const file of idea.affectedFiles) {
   851→      frontmatter.push(`  - ${file}`);
   852→    }
   853→  }
   854→
   855→  // Add existing patterns to frontmatter as YAML array
   856→  if (idea.existingPatterns && idea.existingPatterns.length > 0) {
   857→    frontmatter.push("existing_patterns:");
   858→    for (const pattern of idea.existingPatterns) {
   859→      frontmatter.push(`  - ${pattern}`);
   860→    }
   861→  }
   862→
   863→  frontmatter.push("---");
   864→
   865→  // Body contains implementation approach directly (no header needed)
   866→  const body = idea.implementationApproach || "";
   867→
   868→  const content = frontmatter.join("\n") + "\n\n" + body + "\n";
   869→  writeFileSync(filePath, content, "utf-8");
   870→
   871→  return fileName;
   872→}
   873→
   874→/**
   875→ * Write ideas - each idea to its own file
   876→ *
   877→ * @param sessionDir - Session directory path
   878→ * @param ideas - Array of ideas to write
   879→ * @returns Array of filenames that were written
   880→ */
   881→export function writeIdeasToSeparateFiles(
   882→  sessionDir: string,
   883→  ideas: Idea[]
   884→): string[] {
   885→  const files: string[] = [];
   886→  for (const idea of ideas) {
   887→    const fileName = writeSingleIdeaToFile(sessionDir, idea);
   888→    files.push(fileName);
   889→  }
   890→  return files;
   891→}
   892→
   893→/**
   894→ * Parse ideas from a markdown file
   895→ *
   896→ * Supports both:
   897→ * - Single idea per file (new format): starts with ---\nfrontmatter\n---
   898→ * - Multiple ideas per file (legacy format): multiple --- separated sections
   899→ *
   900→ * Uses gray-matter for robust YAML frontmatter parsing.
   901→ *
   902→ * @param filePath - Path to the idea file
   903→ * @returns Array of parsed ideas
   904→ */
   905→export function readIdeasFromFile(filePath: string): Idea[] {
   906→  if (!existsSync(filePath)) {
   907→    return [];
   908→  }
   909→
   910→  try {
   911→    const content = readFileSync(filePath, "utf-8").trim();
   912→
   913→    // Use gray-matter to parse the file
   914→    const { frontmatter, body } = parseFrontmatter(content);
   915→
   916→    // If frontmatter has an id, this is a single-idea file
   917→    if (frontmatter.id) {
   918→      const idea = parseIdeaFromFrontmatterAndBody(frontmatter, body);
   919→      if (idea) {
   920→        return [idea];
   921→      }
   922→    }
   923→
   924→    // Legacy format: multiple ideas separated by \n---\n
   925→    // This happens when ideas were written with writeIdeasToFile (multiple per file)
   926→    const ideas: Idea[] = [];
   927→    const sections = content.split(/\n---\n+/);
   928→
   929→    for (const section of sections) {
   930→      const trimmed = section.trim();
   931→      if (!trimmed) {
   932→        continue;
   933→      }
   934→
   935→      // Section might start with --- or not (if it was split)
   936→      const sectionToparse = trimmed.startsWith("---")
   937→        ? trimmed
   938→        : "---\n" + trimmed;
   939→      const { frontmatter: fm, body: bd } = parseFrontmatter(sectionToparse);
   940→
   941→      if (fm.id) {
   942→        const idea = parseIdeaFromFrontmatterAndBody(fm, bd);
   943→        if (idea) {
   944→          ideas.push(idea);
   945→        }
   946→      }
   947→    }
   948→
   949→    return ideas;
   950→  } catch {
   951→    return [];
   952→  }
   953→}
   954→
   955→/**
   956→ * Get all ideas from a session
   957→ *
   958→ * @param sessionDir - Session directory path
   959→ * @returns Array of all ideas in the session
   960→ */
   961→export function getAllIdeasFromSession(sessionDir: string): Idea[] {
   962→  const ideas: Idea[] = [];
   963→
   964→  try {
   965→    const files = readdirSync(sessionDir);
   966→    for (const file of files) {
   967→      if (file.startsWith(IDEA_FILE_PREFIX) && file.endsWith(".md")) {
   968→        const filePath = join(sessionDir, file);
   969→        const fileIdeas = readIdeasFromFile(filePath);
   970→        ideas.push(...fileIdeas);
   971→      }
   972→    }
   973→  } catch {
   974→    // Ignore errors
   975→  }
   976→
   977→  return ideas;
   978→}
   979→
   980→/**
   981→ * Find an idea by ID
   982→ *
   983→ * @param repoRoot - Repository root path
   984→ * @param ideaId - Idea ID to find
   985→ * @param customOutput - Optional custom output directory
   986→ * @returns Object with idea and session directory, or null
   987→ */
   988→export function findIdeaById(
   989→  repoRoot: string,
   990→  ideaId: string,
   991→  customOutput?: string
   992→): { idea: Idea; sessionDir: string; filePath: string } | null {
   993→  const sessions = listSessions(repoRoot, customOutput);
   994→
   995→  for (const sessionDir of sessions) {
   996→    try {
   997→      const files = readdirSync(sessionDir);
   998→      for (const file of files) {
   999→        if (file.startsWith(IDEA_FILE_PREFIX) && file.endsWith(".md")) {
  1000→          const filePath = join(sessionDir, file);
  1001→          const ideas = readIdeasFromFile(filePath);
  1002→          const found = ideas.find((i) => i.id === ideaId);
  1003→          if (found) {
  1004→            return { idea: found, sessionDir, filePath };
  1005→          }
  1006→        }
  1007→      }
  1008→    } catch {
  1009→      // Continue to next session
  1010→    }
  1011→  }
  1012→
  1013→  return null;
  1014→}
  1015→
  1016→/**
  1017→ * Update an idea in its file
  1018→ *
  1019→ * @param filePath - Path to the idea file
  1020→ * @param ideaId - ID of the idea to update
  1021→ * @param updates - Partial idea updates
  1022→ * @returns True if updated, false if not found
  1023→ */
  1024→export function updateIdea(
  1025→  filePath: string,
  1026→  ideaId: string,
  1027→  updates: Partial<Idea>
  1028→): boolean {
  1029→  const ideas = readIdeasFromFile(filePath);
  1030→  const index = ideas.findIndex((i) => i.id === ideaId);
  1031→
  1032→  if (index === -1) {
  1033→    return false;
  1034→  }
  1035→
  1036→  ideas[index] = { ...ideas[index], ...updates };
  1037→  writeIdeasToFile(filePath, ideas);
  1038→  return true;
  1039→}
  1040→
  1041→// =============================================================================
  1042→// Idea Query Functions
  1043→// =============================================================================
  1044→
  1045→/**
  1046→ * Get all ideas from all sessions with optional filtering
  1047→ *
  1048→ * @param repoRoot - Repository root path
  1049→ * @param options - Optional filter options
  1050→ * @returns Array of Ideas
  1051→ */
  1052→export function getAllIdeas(
  1053→  repoRoot: string,
  1054→  options?: IdeaListOptions
  1055→): Idea[] {
  1056→  const sessionDirs = listSessions(repoRoot);
  1057→  const allIdeas: Idea[] = [];
  1058→
  1059→  for (const sessionDir of sessionDirs) {
  1060→    const sessionIdeas = getAllIdeasFromSession(sessionDir);
  1061→    allIdeas.push(...sessionIdeas);
  1062→  }
  1063→
  1064→  // Apply filters
  1065→  let filtered = allIdeas;
  1066→
  1067→  if (options?.type) {
  1068→    filtered = filtered.filter((idea) => idea.type === options.type);
  1069→  }
  1070→
  1071→  if (options?.effort) {
  1072→    filtered = filtered.filter(
  1073→      (idea) => idea.estimatedEffort === options.effort
  1074→    );
  1075→  }
  1076→
  1077→  if (options?.status) {
  1078→    filtered = filtered.filter((idea) => idea.status === options.status);
  1079→  }
  1080→
  1081→  return filtered;
  1082→}
  1083→
  1084→/**
  1085→ * Get an idea by its ID
  1086→ *
  1087→ * @param repoRoot - Repository root path
  1088→ * @param ideaId - Idea ID (e.g., "a1b2c3d4")
  1089→ * @returns Idea or null if not found
  1090→ */
  1091→export function getIdeaById(repoRoot: string, ideaId: string): Idea | null {
  1092→  const result = findIdeaById(repoRoot, ideaId);
  1093→  return result ? result.idea : null;
  1094→}
  1095→
  1096→/**
  1097→ * Update an idea's status
  1098→ *
  1099→ * @param repoRoot - Repository root path
  1100→ * @param ideaId - Idea ID
  1101→ * @param status - New status
  1102→ * @param promotedTo - Optional task ID if promoting
  1103→ */
  1104→export function updateIdeaStatus(
  1105→  repoRoot: string,
  1106→  ideaId: string,
  1107→  status: string,
  1108→  promotedTo?: string
  1109→): void {
  1110→  const location = findIdeaById(repoRoot, ideaId);
  1111→  if (!location) {
  1112→    return;
  1113→  }
  1114→
  1115→  const updates: Partial<Idea> = {};
  1116→  if (isValidIdeaStatus(status)) {
  1117→    updates.status = status;
  1118→  }
  1119→  if (promotedTo !== undefined) {
  1120→    updates.promotedTo = promotedTo;
  1121→  }
  1122→
  1123→  updateIdea(location.filePath, ideaId, updates);
  1124→
  1125→  // Update session summary
  1126→  updateSessionSummary(location.sessionDir);
  1127→}
  1128→
  1129→/**
  1130→ * Remove an idea by ID
  1131→ *
  1132→ * @param repoRoot - Repository root path
  1133→ * @param ideaId - Idea ID
  1134→ * @returns True if removed, false if not found
  1135→ */
  1136→export function removeIdea(repoRoot: string, ideaId: string): boolean {
  1137→  const location = findIdeaById(repoRoot, ideaId);
  1138→  if (!location) {
  1139→    return false;
  1140→  }
  1141→
  1142→  const ideas = readIdeasFromFile(location.filePath);
  1143→  const filteredIdeas = ideas.filter((idea) => idea.id !== ideaId);
  1144→
  1145→  if (filteredIdeas.length === ideas.length) {
  1146→    return false; // Not found
  1147→  }
  1148→
  1149→  writeIdeasToFile(location.filePath, filteredIdeas);
  1150→
  1151→  // Update session summary
  1152→  updateSessionSummary(location.sessionDir);
  1153→
  1154→  return true;
  1155→}
  1156→
  1157→/**
  1158→ * Remove all ideas of a specific type
  1159→ *
  1160→ * @param repoRoot - Repository root path
  1161→ * @param type - Idea type to remove
  1162→ * @returns Number of ideas removed
  1163→ */
  1164→export function removeIdeasByType(repoRoot: string, type: string): number {
  1165→  const sessionDirs = listSessions(repoRoot);
  1166→  let removedCount = 0;
  1167→
  1168→  for (const sessionDir of sessionDirs) {
  1169→    const mdPath = getIdeaMarkdownPath(sessionDir, type);
  1170→
  1171→    if (existsSync(mdPath)) {
  1172→      const ideas = readIdeasFromFile(mdPath);
  1173→      removedCount += ideas.length;
  1174→
  1175→      // Remove the file
  1176→      unlinkSync(mdPath);
  1177→
  1178→      // Update session summary
  1179→      updateSessionSummary(sessionDir);
  1180→    }
  1181→  }
  1182→
  1183→  return removedCount;
  1184→}
  1185→
  1186→/**
  1187→ * Remove all ideas
  1188→ *
  1189→ * @param repoRoot - Repository root path
  1190→ * @returns Number of ideas removed
  1191→ */
  1192→export function removeAllIdeas(repoRoot: string): number {
  1193→  const sessions = listIdeaSessions(repoRoot);
  1194→  let removedCount = 0;
  1195→
  1196→  for (const session of sessions) {
  1197→    removedCount += session.summary.total_ideas;
  1198→    const sessionDir = getIdeaSessionDir(repoRoot, session.id);
  1199→
  1200→    // Remove entire session directory
  1201→    if (existsSync(sessionDir)) {
  1202→      rmSync(sessionDir, { recursive: true, force: true });
  1203→    }
  1204→  }
  1205→
  1206→  return removedCount;
  1207→}
  1208→
  1209→/**
  1210→ * Update session summary after modifying ideas
  1211→ *
  1212→ * @param sessionDir - Session directory path
  1213→ */
  1214→function updateSessionSummary(sessionDir: string): void {
  1215→  const session = readSessionMetadata(sessionDir);
  1216→  if (!session) {
  1217→    return;
  1218→  }
  1219→
  1220→  // Recalculate summary
  1221→  session.summary.total_ideas = 0;
  1222→  session.summary.by_type = {};
  1223→  session.summary.by_status = { draft: 0, promoted: 0, dismissed: 0 };
  1224→
  1225→  // Check which types still have files
  1226→  const remainingTypes: string[] = [];
  1227→
  1228→  for (const type of session.types) {
  1229→    const mdPath = getIdeaMarkdownPath(sessionDir, type);
  1230→    if (existsSync(mdPath)) {
  1231→      const ideas = readIdeasFromFile(mdPath);
  1232→
  1233→      if (ideas.length > 0) {
  1234→        remainingTypes.push(type);
  1235→        session.summary.by_type[type] = ideas.length;
  1236→        session.summary.total_ideas += ideas.length;
  1237→
  1238→        for (const idea of ideas) {
  1239→          if (idea.status in session.summary.by_status) {
  1240→            session.summary.by_status[idea.status as IdeaStatus]++;
  1241→          }
  1242→        }
  1243→      }
  1244→    }
  1245→  }
  1246→
  1247→  session.types = remainingTypes;
  1248→  session.updated_at = new Date().toISOString();
  1249→  writeIdeaSession(sessionDir, session);
  1250→}
