   892→
   893→/**
   894→ * Parse ideas from a markdown file
   895→ *
   896→ * Supports both:
   897→ * - Single idea per file (new format): starts with ---\nfrontmatter\n---
   898→ * - Multiple ideas per file (legacy format): multiple --- separated sections
   899→ *
   900→ * Uses gray-matter for robust YAML frontmatter parsing.
   901→ *
   902→ * @param filePath - Path to the idea file
   903→ * @returns Array of parsed ideas
   904→ */
   905→export function readIdeasFromFile(filePath: string): Idea[] {
   906→  if (!existsSync(filePath)) {
   907→    return [];
   908→  }
   909→
   910→  try {
   911→    const content = readFileSync(filePath, "utf-8").trim();
   912→
   913→    // Use gray-matter to parse the file
   914→    const { frontmatter, body } = parseFrontmatter(content);
   915→
   916→    // If frontmatter has an id, this is a single-idea file
   917→    if (frontmatter.id) {
   918→      const idea = parseIdeaFromFrontmatterAndBody(frontmatter, body);
   919→      if (idea) {
   920→        return [idea];
   921→      }
   922→    }
   923→
   924→    // Legacy format: multiple ideas separated by \n---\n
   925→    // This happens when ideas were written with writeIdeasToFile (multiple per file)
   926→    const ideas: Idea[] = [];
   927→    const sections = content.split(/\n---\n+/);
   928→
   929→    for (const section of sections) {
   930→      const trimmed = section.trim();
   931→      if (!trimmed) {
   932→        continue;
   933→      }
   934→
   935→      // Section might start with --- or not (if it was split)
   936→      const sectionToparse = trimmed.startsWith("---")
   937→        ? trimmed
   938→        : "---\n" + trimmed;
   939→      const { frontmatter: fm, body: bd } = parseFrontmatter(sectionToparse);
   940→
   941→      if (fm.id) {
   942→        const idea = parseIdeaFromFrontmatterAndBody(fm, bd);
   943→        if (idea) {
   944→          ideas.push(idea);
   945→        }
   946→      }
   947→    }
   948→
   949→    return ideas;
   950→  } catch {
   951→    return [];
   952→  }
   953→}
   954→
   955→/**
   956→ * Get all ideas from a session
   957→ *
   958→ * @param sessionDir - Session directory path
   959→ * @returns Array of all ideas in the session
   960→ */
   961→export function getAllIdeasFromSession(sessionDir: string): Idea[] {
   962→  const ideas: Idea[] = [];
   963→
   964→  try {
   965→    const files = readdirSync(sessionDir);
   966→    for (const file of files) {
   967→      if (file.startsWith(IDEA_FILE_PREFIX) && file.endsWith(".md")) {
   968→        const filePath = join(sessionDir, file);
   969→        const fileIdeas = readIdeasFromFile(filePath);
   970→        ideas.push(...fileIdeas);
   971→      }
   972→    }
   973→  } catch {
   974→    // Ignore errors
   975→  }
   976→
   977→  return ideas;
   978→}
   979→
   980→/**
   981→ * Find an idea by ID
   982→ *
   983→ * @param repoRoot - Repository root path
   984→ * @param ideaId - Idea ID to find
   985→ * @param customOutput - Optional custom output directory
   986→ * @returns Object with idea and session directory, or null
   987→ */
   988→export function findIdeaById(
   989→  repoRoot: string,
   990→  ideaId: string,
   991→  customOutput?: string
   992→): { idea: Idea; sessionDir: string; filePath: string } | null {
   993→  const sessions = listSessions(repoRoot, customOutput);
   994→
   995→  for (const sessionDir of sessions) {
   996→    try {
   997→      const files = readdirSync(sessionDir);
   998→      for (const file of files) {
   999→        if (file.startsWith(IDEA_FILE_PREFIX) && file.endsWith(".md")) {
  1000→          const filePath = join(sessionDir, file);
  1001→          const ideas = readIdeasFromFile(filePath);
  1002→          const found = ideas.find((i) => i.id === ideaId);
  1003→          if (found) {
  1004→            return { idea: found, sessionDir, filePath };
  1005→          }
  1006→        }
  1007→      }
  1008→    } catch {
  1009→      // Continue to next session
  1010→    }
  1011→  }
  1012→
  1013→  return null;
  1014→}
  1015→
  1016→/**
  1017→ * Update an idea in its file
  1018→ *
  1019→ * @param filePath - Path to the idea file
  1020→ * @param ideaId - ID of the idea to update
  1021→ * @param updates - Partial idea updates
  1022→ * @returns True if updated, false if not found
  1023→ */
  1024→export function updateIdea(
  1025→  filePath: string,
  1026→  ideaId: string,
  1027→  updates: Partial<Idea>
  1028→): boolean {
  1029→  const ideas = readIdeasFromFile(filePath);
  1030→  const index = ideas.findIndex((i) => i.id === ideaId);
  1031→
  1032→  if (index === -1) {
  1033→    return false;
  1034→  }
  1035→
  1036→  ideas[index] = { ...ideas[index], ...updates };
  1037→  writeIdeasToFile(filePath, ideas);
  1038→  return true;
  1039→}
