    51→/**
    52→ * Check if a provider type has any configured provider with API key
    53→ *
    54→ * This checks by provider TYPE (e.g., "anthropic", "openai") rather than
    55→ * provider ID (e.g., "本地-claude"), because KNOWN_MODELS use type names.
    56→ */
    57→async function isProviderAvailable(providerType: string): Promise<boolean> {
    58→  try {
    59→    const providers = await providerManager.listProviders();
    60→    // Find any enabled provider of this type with API key configured
    61→    return providers.some((p) => {
    62→      if (p.type !== providerType) return false;
    63→      if (!p.enabled) return false;
    64→      // Ollama doesn't need API key
    65→      if (p.type === "ollama") return true;
    66→      return !!p.apiKey;
    67→    });
    68→  } catch {
    69→    return false;
    70→  }
    71→}
