    73→/**
    74→ * Transform model to API response format (snake_case)
    75→ *
    76→ * Now uses model.isDefault and model.enabled from ModelManager
    77→ * instead of in-memory tracking.
    78→ */
    79→async function toSnakeCaseModel(model: Model): Promise<ModelResponse> {
    80→  const now = new Date().toISOString();
    81→  const isAvailable = await isProviderAvailable(model.provider);
    82→  return {
    83→    id: model.id,
    84→    name: model.name,
    85→    provider: model.provider,
    86→    provider_id: model.provider,
    87→    provider_name: model.provider,
    88→    description: model.description,
    89→    context_window: model.contextLength,
    90→    max_output_tokens: model.maxOutputTokens,
    91→    input_price: model.inputPrice,
    92→    output_price: model.outputPrice,
    93→    is_default: model.isDefault ?? false,
    94→    enabled: model.enabled ?? true,
    95→    is_available: isAvailable,
    96→    created_at: model.created_at ?? now,
    97→    updated_at: model.updated_at ?? now,
    98→  };
    99→}
