## 5. Gateway route file pattern — `providers.ts` and `models.ts`

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/gateway/routes/providers.ts`
`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/gateway/routes/models.ts`

The canonical pattern for a CRUD route file:

```ts
import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import { someSingleton } from "../../some-module";
import type { SomeType } from "../../types";

// ── Local request/response interfaces (snake_case) ────────────────────────
interface CreateFooBody { name: string; some_field?: string; }
interface UpdateFooBody { name?: string; some_field?: string; }

// ── Transform helper (camelCase internal → snake_case API) ─────────────────
function toApiShape(foo: InternalFoo): FooResponse { ... }

// ── Route registration ─────────────────────────────────────────────────────
export function registerFooRoutes(fastify: FastifyInstance): void {

  // Static/named routes BEFORE :id param routes (Fastify ordering matters)
  fastify.get("/api/foos/default", async () => { ... });
  fastify.put("/api/foos/default", async (req: FastifyRequest<{ Body: SetDefaultBody }>, reply) => { ... });

  // List
  fastify.get("/api/foos", {
    schema: { description: "...", tags: ["foos"], response: { 200: { ... } } }
  }, async (req: FastifyRequest<{ Querystring: FoosQuery }>) => {
    const items = await someSingleton.list();
    return { foos: items.map(toApiShape), total: items.length };
  });

  // Create  → 201
  fastify.post("/api/foos", async (req: FastifyRequest<{ Body: CreateFooBody }>, reply) => {
    if (!req.body.name) { reply.code(400); return { error: "name is required" }; }
    try {
      const item = await someSingleton.create(req.body);
      reply.code(201);
      return toApiShape(item);
    } catch (e) {
      reply.code(400);
      return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Get by ID
  fastify.get("/api/foos/:id", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    const item = await someSingleton.get(req.params.id);
    if (!item) { reply.code(404); return { error: `Not found: ${req.params.id}` }; }
    return toApiShape(item);
  });

  // Update  → PATCH
  fastify.patch("/api/foos/:id", async (
    req: FastifyRequest<{ Params: { id: string }; Body: UpdateFooBody }>,
    reply
  ) => {
    try {
      const updated = await someSingleton.update(req.params.id, req.body);
      return toApiShape(updated);
    } catch (e) {
      if (e instanceof Error && e.message.includes("not found")) {
        reply.code(404); return { error: `Not found: ${req.params.id}` };
      }
      reply.code(400); return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Delete
  fastify.delete("/api/foos/:id", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    try {
      await someSingleton.remove(req.params.id);
      return { success: true, deleted: req.params.id };
    } catch (e) {
      reply.code(e instanceof Error && e.message.includes("not found") ? 404 : 400);
      return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Action sub-routes (enable/disable/test)
  fastify.post("/api/foos/:id/enable", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    try {
      await someSingleton.setEnabled(req.params.id, true);
      return { success: true, id: req.params.id, enabled: true };
    } catch (e) { ... }
  });
}
```

**Key conventions to follow:**

- All request/response types defined locally at the top of the file as plain interfaces
- API response fields use `snake_case`; internal model fields may be `camelCase` — a `toApiShape()` transformer bridges them
- Named/static routes (`/default`, `/reload`, `/aliases`) registered BEFORE parameterized routes (`/:id`) to avoid Fastify treating "default" as an `:id` value
- Error handling: `reply.code(400/404/500)` then return `{ error: string }` — no thrown HTTP errors
- `schema:` object is optional but used on GET list endpoints for documentation
- Delete returns `{ success: true, deleted: id }`, not 204
- Singleton managers (like `providerManager`, `modelManager`) are imported from `../../providers` / `../../models` — no DI

Here is everything you need, shown as actual code with all the key patterns.

---

## 1. `packages/core/src/config/paths.ts` — Path utilities

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/config/paths.ts`

The pattern is straightforward exported functions, no classes:

```ts
import { homedir } from "node:os";
import { join } from "node:path";

export function getStateDir(): string {
  return process.env.VIBEN_STATE_DIR || join(homedir(), ".viben");
}

export function getProvidersPath(): string {
  return join(getStateDir(), "providers.yaml");
}

// Every new subsystem gets its own path function:
export function getFooDir(): string {
  return join(getStateDir(), "foo");
}
export function getFooFilePath(id: string): string {
  return join(getFooDir(), `${id}.yaml`);
}
```

No class, no singleton. Each function calls `getStateDir()` freshly (respects `VIBEN_STATE_DIR` env override at call time).

---

## 2. `packages/core/src/idea/ops/store.ts` — File storage patterns

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/idea/ops/store.ts`

This is the most relevant example because it uses JSON for metadata and markdown+frontmatter for content. There is NO yaml-js usage here — it uses `gray-matter` for frontmatter parsing. Key patterns:

**Read JSON:**
```ts
const content = readFileSync(jsonPath, "utf-8");
const raw = JSON.parse(content) as RawIdeaSession;
```

**Write JSON:**
```ts
writeFileSync(jsonPath, JSON.stringify(session, null, 2), "utf-8");
```

**Read YAML frontmatter (markdown files):**
```ts
import matter from "gray-matter";

function parseFrontmatter(content: string) {
  const parsed = matter(content);
  return { frontmatter: parsed.data, body: parsed.content };
}
```

**Write YAML frontmatter manually (no yaml serializer, just string templates):**
```ts
const frontmatterLines = [
  "---",
  `name: ${input.name}`,
  `description: ${input.description}`,
  "---",
];
const content = frontmatterLines.join("\n") + "\n\n" + promptContent;
writeFileSync(promptPath, content, "utf-8");
```

**Ensure directory exists before writing:**
```ts
if (!existsSync(dir)) {
  mkdirSync(dir, { recursive: true });
}
```

**Guard reads:**
```ts
if (!existsSync(filePath)) return null;
try { ... } catch { return null; }
```

If you need a YAML-native store (providers/models use it), look for the actual providerManager/modelManager source — but `idea/ops/store.ts` shows the manual frontmatter-as-string pattern that is used throughout.

---

## 3. `packages/core/src/cli/commands/index.ts` — Command registration

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/cli/commands/index.ts`

```ts
import type { Command } from "commander";
import { registerFooCommand } from "./foo";

export function registerCommands(program: Command): void {
  registerFooCommand(program);
  // ...
}
```

Each command lives in its own file (`./foo.ts`) that exports `registerFooCommand(program: Command): void`. The file just calls `program.command(...)` inside that function. To add a new command: create the file, add an import, and add one call in `registerCommands`.

---

## 4. `packages/core/src/gateway/routes/index.ts` — Route registration

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/gateway/routes/index.ts`

```ts
import type { FastifyInstance } from "fastify";
import type { AppState } from "../state";
import { registerFooRoutes } from "./foo";

export function registerRoutes(fastify: FastifyInstance, state: AppState): void {
  registerFooRoutes(fastify);           // stateless routes
  registerBarRoutes(fastify, state);    // stateful routes need state
}

// Also re-exports every registration function for external use
export { registerFooRoutes } from "./foo";
```

Routes that need background services (SSE, sessions, queues) receive `state`. Purely CRUD routes for config files (providers, models, ideas, skills) receive only `fastify`.

---

## 5. Gateway route file pattern — `providers.ts` and `models.ts`

`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/gateway/routes/providers.ts`
`/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/packages/core/src/gateway/routes/models.ts`

The canonical pattern for a CRUD route file:

```ts
import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import { someSingleton } from "../../some-module";
import type { SomeType } from "../../types";

// ── Local request/response interfaces (snake_case) ────────────────────────
interface CreateFooBody { name: string; some_field?: string; }
interface UpdateFooBody { name?: string; some_field?: string; }

// ── Transform helper (camelCase internal → snake_case API) ─────────────────
function toApiShape(foo: InternalFoo): FooResponse { ... }

// ── Route registration ─────────────────────────────────────────────────────
export function registerFooRoutes(fastify: FastifyInstance): void {

  // Static/named routes BEFORE :id param routes (Fastify ordering matters)
  fastify.get("/api/foos/default", async () => { ... });
  fastify.put("/api/foos/default", async (req: FastifyRequest<{ Body: SetDefaultBody }>, reply) => { ... });

  // List
  fastify.get("/api/foos", {
    schema: { description: "...", tags: ["foos"], response: { 200: { ... } } }
  }, async (req: FastifyRequest<{ Querystring: FoosQuery }>) => {
    const items = await someSingleton.list();
    return { foos: items.map(toApiShape), total: items.length };
  });

  // Create  → 201
  fastify.post("/api/foos", async (req: FastifyRequest<{ Body: CreateFooBody }>, reply) => {
    if (!req.body.name) { reply.code(400); return { error: "name is required" }; }
    try {
      const item = await someSingleton.create(req.body);
      reply.code(201);
      return toApiShape(item);
    } catch (e) {
      reply.code(400);
      return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Get by ID
  fastify.get("/api/foos/:id", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    const item = await someSingleton.get(req.params.id);
    if (!item) { reply.code(404); return { error: `Not found: ${req.params.id}` }; }
    return toApiShape(item);
  });

  // Update  → PATCH
  fastify.patch("/api/foos/:id", async (
    req: FastifyRequest<{ Params: { id: string }; Body: UpdateFooBody }>,
    reply
  ) => {
    try {
      const updated = await someSingleton.update(req.params.id, req.body);
      return toApiShape(updated);
    } catch (e) {
      if (e instanceof Error && e.message.includes("not found")) {
        reply.code(404); return { error: `Not found: ${req.params.id}` };
      }
      reply.code(400); return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Delete
  fastify.delete("/api/foos/:id", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    try {
      await someSingleton.remove(req.params.id);
      return { success: true, deleted: req.params.id };
    } catch (e) {
      reply.code(e instanceof Error && e.message.includes("not found") ? 404 : 400);
      return { error: e instanceof Error ? e.message : "Failed" };
    }
  });

  // Action sub-routes (enable/disable/test)
  fastify.post("/api/foos/:id/enable", async (req: FastifyRequest<{ Params: { id: string } }>, reply) => {
    try {
      await someSingleton.setEnabled(req.params.id, true);
      return { success: true, id: req.params.id, enabled: true };
    } catch (e) { ... }
  });
}
```

**Key conventions to follow:**

- All request/response types defined locally at the top of the file as plain interfaces
- API response fields use `snake_case`; internal model fields may be `camelCase` — a `toApiShape()` transformer bridges them
- Named/static routes (`/default`, `/reload`, `/aliases`) registered BEFORE parameterized routes (`/:id`) to avoid Fastify treating "default" as an `:id` value
- Error handling: `reply.code(400/404/500)` then return `{ error: string }` — no thrown HTTP errors
- `schema:` object is optional but used on GET list endpoints for documentation
- Delete returns `{ success: true, deleted: id }`, not 204
- Singleton managers (like `providerManager`, `modelManager`) are imported from `../../providers` / `../../models` — no DI

