  1655→        setSelectedExchange(exRes.exchanges[0].id);
  1656→      }
  1657→    } catch {
  1658→      toast.error("Failed to load exchange data");
  1659→    }
  1660→  }, [selectedExchange]);
  1661→
  1662→  useEffect(() => {
  1663→    if (open) fetchData();
  1664→  }, [open, fetchData]);
  1665→
  1666→  const currentExchange = exchanges.find((e) => e.id === selectedExchange);
  1667→  const exchangeAccounts = accounts.filter((a) => a.exchange === selectedExchange);
  1668→
  1669→  const resetForm = () => {
  1670→    const count = exchangeAccounts.length + 1;
  1671→    setFormName(`${currentExchange?.name ?? ""} #${count}`);
  1672→    setFormApiKey("");
  1673→    setFormSecret("");
  1674→    setFormPassphrase("");
