  1686→    setShowForm(true);
  1687→  };
  1688→
  1689→  const handleSave = async () => {
  1690→    setSaving(true);
  1691→    try {
  1692→      const body: Record<string, string> = {
  1693→        exchange: selectedExchange,
  1694→        name: formName,
  1695→        api_key: formApiKey,
  1696→        secret: formSecret,
  1697→      };
