  1699→
  1700→      const res = await fetch(`${GATEWAY}/api/accounts`, {
  1701→        method: "POST",
  1702→        headers: { "Content-Type": "application/json" },
  1703→        body: JSON.stringify(body),
  1704→      });
  1705→      const data = await res.json();
  1706→      if (data.success) {
  1707→        toast.success("账户添加成功");
  1708→        setShowForm(false);
  1709→        await fetchData();
  1710→      } else {
  1711→        toast.error(data.error ?? "保存失败");
  1712→      }
  1713→    } catch {
  1714→      toast.error("网络错误");
  1715→    } finally {
  1716→      setSaving(false);
  1717→    }
  1718→  };
  1719→
  1720→  const handleTest = async (id: string) => {
  1721→    toast.info("测试连接中...");
  1722→    try {
  1723→      const res = await fetch(`${GATEWAY}/api/accounts/${id}/test`, { method: "POST" });
  1724→      const data = await res.json();
  1725→      if (data.success) {
  1726→        toast.success(`连接成功 (${data.latency_ms}ms)`);
  1727→      } else {
  1728→        toast.error(`连接失败: ${data.error}`);
  1729→      }
  1730→    } catch {
  1731→      toast.error("网络错误");
  1732→    }
  1733→  };
  1734→
  1735→  const handleDelete = async (id: string) => {
  1736→    if (!confirm("确认删除该账户？")) return;
  1737→    try {
  1738→      const res = await fetch(`${GATEWAY}/api/accounts/${id}`, { method: "DELETE" });
  1739→      const data = await res.json();
  1740→      if (data.success) {
  1741→        toast.success("账户已删除");
  1742→        await fetchData();
  1743→      } else {
  1744→        toast.error(data.error ?? "删除失败");
  1745→      }
  1746→    } catch {
  1747→      toast.error("网络错误");
  1748→    }
  1749→  };
  1750→
  1751→  return (
  1752→    <Dialog open={open} onOpenChange={onOpenChange}>
