    const url = queryString
      ? `${BASE_URL}${path}?${queryString}`
      : `${BASE_URL}${path}`;

    return {
      url,
      headers: {
        KEY: credentials.api_key,
        SIGN: signature,
        Timestamp: timestamp,
        "Content-Type": "application/json",
      },
