import {
  listAccounts,
  addAccount,
  viewAccount,
  updateAccount,
  removeAccount,
  testAccount,
  listExchanges,
} from "../../account";
import type { ExchangeId } from "../../account";

interface CreateAccountBody {
  exchange: ExchangeId;
