   262→- [ ] **Step 2: Create OKX adapter**
   263→
   264→```typescript
   265→// packages/core/src/account/ops/exchanges/okx.ts
   266→
   267→import { createHmac } from "node:crypto";
   268→import type { Exchange, Credentials, SignParams, SignedRequest } from "./types";
   269→import type { TestResult } from "../types";
   270→
   271→const BASE_URL = "https://www.okx.com";
   272→
   273→export const okxExchange: Exchange = {
   274→  id: "okx",
   275→  name: "OKX",
   276→  fields: ["api_key", "secret", "passphrase"],
   277→  referral_url: "https://okx.com/join/80926498",
   278→  api_doc_url: "https://www.okx.com/account/my-api",
   279→
   280→  sign(credentials: Credentials, params: SignParams): SignedRequest {
   281→    const { method, path, body } = params;
   282→    const timestamp = params.timestamp;
   283→    const prehash = timestamp + method + path + (body ?? "");
   284→    const signature = createHmac("sha256", credentials.secret)
   285→      .update(prehash)
   286→      .digest("base64");
   287→
   288→    return {
   289→      url: BASE_URL + path,
   290→      headers: {
   291→        "OK-ACCESS-KEY": credentials.api_key,
   292→        "OK-ACCESS-SIGN": signature,
   293→        "OK-ACCESS-TIMESTAMP": timestamp,
   294→        "OK-ACCESS-PASSPHRASE": credentials.passphrase ?? "",
   295→        "Content-Type": "application/json",
   296→      },
   297→    };
   298→  },
   299→
   300→  async testConnection(credentials: Credentials): Promise<TestResult> {
   301→    const timestamp = new Date().toISOString();
   302→    const path = "/api/v5/account/balance";
   303→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
   304→
   305→    const start = Date.now();
   306→    try {
   307→      const res = await fetch(signed.url, {
   308→        method: "GET",
   309→        headers: signed.headers,
   310→        signal: AbortSignal.timeout(10_000),
   311→      });
   312→      const latency_ms = Date.now() - start;
   313→      const json = (await res.json()) as { code?: string; msg?: string };
   314→
   315→      if (json.code === "0") {
   316→        return { success: true, latency_ms };
   317→      }
   318→      return { success: false, error: json.msg ?? `Error code: ${json.code}`, latency_ms };
   319→    } catch (e) {
   320→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
   321→    }
   322→  },
   323→};
   324→```
