   821→// packages/core/src/account/ops/crud.ts
   822→
   823→import { nanoid } from "nanoid";
   824→import { readAccounts, writeAccounts, maskCredential } from "./store";
   825→import { getExchange } from "./exchanges";
   826→import type {
   827→  ExchangeId,
   828→  CredentialField,
   829→  Account,
   830→  AccountRecord,
   831→  CreateAccountResult,
   832→  UpdateAccountResult,
   833→  ListAccountsResult,
   834→  ViewAccountResult,
   835→  RemoveAccountResult,
   836→} from "./types";
   837→
   838→const MAX_NAME_LENGTH = 64;
   839→const MAX_CREDENTIAL_LENGTH = 256;
   840→
   841→function validateCredential(value: string, field: string): string | null {
   842→  const trimmed = value.trim();
   843→  if (!trimmed) return `${field} cannot be empty`;
   844→  if (trimmed.length > MAX_CREDENTIAL_LENGTH) return `${field} exceeds max length (${MAX_CREDENTIAL_LENGTH})`;
   845→  return null;
   846→}
   847→
   848→function validateName(name: string): string | null {
   849→  const trimmed = name.trim();
   850→  if (!trimmed) return "name cannot be empty";
   851→  if (trimmed.length > MAX_NAME_LENGTH) return `name exceeds max length (${MAX_NAME_LENGTH})`;
   852→  return null;
   853→}
   854→
   855→function toAccount(record: AccountRecord): Account {
   856→  return {
   857→    id: record.id,
   858→    exchange: record.exchange,
   859→    name: record.name,
   860→    created_at: record.created_at,
   861→    updated_at: record.updated_at,
   862→  };
   863→}
   864→
   865→export async function findAccount(idOrName: string): Promise<AccountRecord | null> {
   866→  const accounts = await readAccounts();
   867→  // 1. Match by ID
   868→  const byId = accounts.find((a) => a.id === idOrName);
   869→  if (byId) return byId;
   870→  // 2. Match by name (exact, case-sensitive)
   871→  const byName = accounts.filter((a) => a.name === idOrName);
   872→  if (byName.length === 1) return byName[0];
   873→  if (byName.length > 1) return null; // ambiguous
   874→  return null;
   875→}
   876→
   877→export async function listAccounts(): Promise<ListAccountsResult> {
   878→  const accounts = await readAccounts();
   879→  return { success: true, accounts: accounts.map(toAccount) };
   880→}
   881→
   882→export async function addAccount(input: {
   883→  exchange: ExchangeId;
   884→  name: string;
   885→  api_key: string;
   886→  secret: string;
   887→  passphrase?: string;
   888→}): Promise<CreateAccountResult> {
   889→  // Validate
   890→  const nameErr = validateName(input.name);
   891→  if (nameErr) return { success: false, error: nameErr };
   892→
   893→  const keyErr = validateCredential(input.api_key, "api_key");
   894→  if (keyErr) return { success: false, error: keyErr };
   895→
   896→  const secretErr = validateCredential(input.secret, "secret");
   897→  if (secretErr) return { success: false, error: secretErr };
   898→
   899→  const exchange = getExchange(input.exchange);
   900→  if (exchange.fields.includes("passphrase")) {
   901→    if (!input.passphrase) return { success: false, error: "passphrase is required for " + exchange.name };
   902→    const ppErr = validateCredential(input.passphrase, "passphrase");
   903→    if (ppErr) return { success: false, error: ppErr };
   904→  }
   905→
   906→  const now = new Date().toISOString();
   907→  const record: AccountRecord = {
   908→    id: nanoid(12),
   909→    exchange: input.exchange,
   910→    name: input.name.trim(),
   911→    api_key: input.api_key.trim(),
   912→    secret: input.secret.trim(),
   913→    passphrase: input.passphrase?.trim(),
   914→    created_at: now,
   915→    updated_at: now,
   916→  };
   917→
   918→  const accounts = await readAccounts();
   919→  accounts.push(record);
   920→  await writeAccounts(accounts);
   921→
   922→  return { success: true, account: toAccount(record) };
   923→}
   924→
   925→export async function viewAccount(idOrName: string): Promise<ViewAccountResult> {
   926→  const record = await findAccount(idOrName);
   927→  if (!record) {
   928→    // Check if ambiguous name
   929→    const accounts = await readAccounts();
   930→    const byName = accounts.filter((a) => a.name === idOrName);
   931→    if (byName.length > 1) {
   932→      return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   933→    }
   934→    return { success: false, error: `Account not found: ${idOrName}` };
   935→  }
   936→
   937→  const exchange = getExchange(record.exchange);
   938→  const masked: Partial<Record<CredentialField, string>> = {};
   939→  for (const field of exchange.fields) {
   940→    const value = record[field as keyof AccountRecord] as string | undefined;
   941→    if (value) masked[field] = maskCredential(value);
   942→  }
   943→
   944→  return { success: true, account: toAccount(record), masked_credentials: masked };
   945→}
   946→
   947→export async function updateAccount(idOrName: string, input: {
   948→  name?: string;
   949→  api_key?: string;
   950→  secret?: string;
   951→  passphrase?: string;
   952→}): Promise<UpdateAccountResult> {
   953→  const accounts = await readAccounts();
   954→  // Check for ambiguous name match
   955→  const byName = accounts.filter((a) => a.name === idOrName);
   956→  if (byName.length > 1) {
   957→    return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   958→  }
   959→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   960→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   961→
   962→  const record = accounts[idx];
   963→
   964→  if (input.name) {
   965→    const nameErr = validateName(input.name);
   966→    if (nameErr) return { success: false, error: nameErr };
   967→    record.name = input.name.trim();
   968→  }
   969→  if (input.api_key) {
   970→    const err = validateCredential(input.api_key, "api_key");
   971→    if (err) return { success: false, error: err };
   972→    record.api_key = input.api_key.trim();
   973→  }
   974→  if (input.secret) {
   975→    const err = validateCredential(input.secret, "secret");
   976→    if (err) return { success: false, error: err };
   977→    record.secret = input.secret.trim();
   978→  }
   979→  if (input.passphrase !== undefined) {
   980→    if (input.passphrase) {
   981→      const err = validateCredential(input.passphrase, "passphrase");
   982→      if (err) return { success: false, error: err };
   983→      record.passphrase = input.passphrase.trim();
   984→    } else {
   985→      record.passphrase = undefined;
   986→    }
   987→  }
   988→
   989→  record.updated_at = new Date().toISOString();
   990→  accounts[idx] = record;
   991→  await writeAccounts(accounts);
   992→
   993→  return { success: true, account: toAccount(record) };
   994→}
   995→
   996→export async function removeAccount(idOrName: string): Promise<RemoveAccountResult> {
   997→  const accounts = await readAccounts();
   998→  const byName = accounts.filter((a) => a.name === idOrName);
   999→  if (byName.length > 1) {
  1000→    return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
  1001→  }
  1002→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
  1003→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
  1004→
  1005→  accounts.splice(idx, 1);
  1006→  await writeAccounts(accounts);
  1007→
  1008→  return { success: true };
  1009→}
  1010→```
