  1305→  api_key?: string;
  1306→  secret?: string;
  1307→  passphrase?: string;
  1308→}
  1309→
  1310→export function registerAccountsRoutes(fastify: FastifyInstance): void {
  1311→  // GET /api/exchanges — exchange registry (static meta)
  1312→  fastify.get("/api/exchanges", async () => {
  1313→    const exchanges = listExchanges();
  1314→    return {
  1315→      exchanges: exchanges.map((ex) => ({
  1316→        id: ex.id,
  1317→        name: ex.name,
  1318→        fields: ex.fields,
  1319→        referral_url: ex.referral_url,
  1320→        api_doc_url: ex.api_doc_url,
  1321→        whitelist_ip: ex.whitelist_ip,
  1322→      })),
  1323→    };
  1324→  });
  1325→
  1326→  // GET /api/accounts — list all (no credentials)
  1327→  fastify.get("/api/accounts", async () => {
  1328→    const result = await listAccounts();
  1329→    return result;
  1330→  });
  1331→
  1332→  // POST /api/accounts — create
  1333→  fastify.post("/api/accounts", async (
  1334→    req: FastifyRequest<{ Body: CreateAccountBody }>,
  1335→    reply,
  1336→  ) => {
  1337→    const { exchange, name, api_key, secret, passphrase } = req.body;
  1338→    if (!exchange || !name || !api_key || !secret) {
  1339→      reply.code(400);
  1340→      return { success: false, error: "exchange, name, api_key, and secret are required" };
  1341→    }
  1342→    const result = await addAccount({ exchange, name, api_key, secret, passphrase });
  1343→    if (!result.success) {
  1344→      reply.code(400);
  1345→      return result;
  1346→    }
  1347→    reply.code(201);
  1348→    return result;
  1349→  });
  1350→
  1351→  // GET /api/accounts/:id — view (masked credentials)
  1352→  fastify.get("/api/accounts/:id", async (
  1353→    req: FastifyRequest<{ Params: { id: string } }>,
  1354→    reply,
