  1367→    reply,
  1368→  ) => {
  1369→    const result = await updateAccount(req.params.id, req.body);
  1370→    if (!result.success) {
  1371→      reply.code(result.error?.includes("not found") ? 404 : 400);
  1372→      return result;
  1373→    }
  1374→    return result;
  1375→  });
  1376→
  1377→  // DELETE /api/accounts/:id
  1378→  fastify.delete("/api/accounts/:id", async (
  1379→    req: FastifyRequest<{ Params: { id: string } }>,
  1380→    reply,
  1381→  ) => {
  1382→    const result = await removeAccount(req.params.id);
  1383→    if (!result.success) {
  1384→      reply.code(404);
  1385→      return result;
  1386→    }
  1387→    return result;
  1388→  });
  1389→
