        api_key: "key",
        secret: "secret",
      });
      expect(result.success).toBe(false);
      expect(result.error).toContain("max length");
    });

    it("trims whitespace from credentials", async () => {
      const result = await addAccount({
        exchange: "binance",
        name: "  Binance  ",
        api_key: "  key  ",
